35	 * @author Michael Isvy
36	 */
37	@Entity
38	@Table(name = "owners")
39	public class Owner extends Person {
40	    @Column(name = "address")
41	    @NotEmpty
42	    private String address;
43	
44	    @Column(name = "city")
45	    @NotEmpty
46	    private String city;
47	
48	    @Column(name = "telephone")
49	    @NotEmpty
50	    @Pattern(regexp = "^\\+[0-9]{8,15}$", message = "Telephone must be in E.164 form (a '+' followed by 8 to 15 digits)")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "customer_code")
60	    private String customerCode;
61	
62	    @Column(name = "household_id")
63	    private String householdId;
64	
65	    @Column(name = "namesake_count")
66	    private Integer namesakeCount;
67	
68	    @Column(name = "household_member_count")
69	    private Integer householdMemberCount;
70	
71	    @Column(name = "membership_number")
72	    private String membershipNumber;
73	
74	    @Column(name = "bulk_signup_warning")
75	    private Boolean bulkSignupWarning;
76	
77	    @Column(name = "postcode")
78	    private String postcode;
79	
80	    @Column(name = "possible_duplicate")
81	    private Boolean possibleDuplicate;
82	
83	    @Column(name = "possible_duplicate_of")
84	    private Integer possibleDuplicateOf;
85	
86	    @Column(name = "birth_date")
87	    private LocalDate birthDate;
88	
89	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
90	    private Set<Pet> pets;
91	
92	    public String getAddress() {
93	        return this.address;
94	    }
95	
96	    public void setAddress(String address) {
97	        this.address = address;
98	    }
99	
100	    public String getCity() {
101	        return this.city;
102	    }
103	
104	    public void setCity(String city) {
105	        this.city = city;
106	    }
107	
108	    public String getTelephone() {
109	        return this.telephone;
110	    }
111	
112	    public void setTelephone(String telephone) {
113	        this.telephone = telephone;
114	    }
115	
116	    public String getEmail() {
117	        return this.email;
118	    }
119	
120	    public void setEmail(String email) {
121	        this.email = email;
122	    }
123	
124	    public LocalDate getRegistrationDate() {
125	        return this.registrationDate;
126	    }
127	
128	    public void setRegistrationDate(LocalDate registrationDate) {
129	        this.registrationDate = registrationDate;
130	    }
131	
132	    public String getCustomerCode() {
133	        return this.customerCode;
134	    }
135	
136	    public void setCustomerCode(String customerCode) {
137	        this.customerCode = customerCode;
138	    }
139	
140	    public String getHouseholdId() {
141	        return this.householdId;
142	    }
143	
144	    public void setHouseholdId(String householdId) {
145	        this.householdId = householdId;
146	    }
147	
148	    public Integer getNamesakeCount() {
149	        return this.namesakeCount;
150	    }
151	
152	    public void setNamesakeCount(Integer namesakeCount) {
153	        this.namesakeCount = namesakeCount;
154	    }
155	
156	    public Integer getHouseholdMemberCount() {
157	        return this.householdMemberCount;
158	    }
159	
160	    public void setHouseholdMemberCount(Integer householdMemberCount) {
161	        this.householdMemberCount = householdMemberCount;
162	    }
163	
164	    public String getMembershipNumber() {
165	        return this.membershipNumber;
166	    }
167	
168	    public void setMembershipNumber(String membershipNumber) {
169	        this.membershipNumber = membershipNumber;
170	    }
171	
172	    public Boolean getBulkSignupWarning() {
173	        return this.bulkSignupWarning;
174	    }
175	
176	    public void setBulkSignupWarning(Boolean bulkSignupWarning) {
177	        this.bulkSignupWarning = bulkSignupWarning;
178	    }
179	
180	    public String getPostcode() {
181	        return this.postcode;
182	    }
183	
184	    public void setPostcode(String postcode) {
185	        this.postcode = postcode;
186	    }
187	
188	    public Boolean getPossibleDuplicate() {
189	        return this.possibleDuplicate;
190	    }
191	
192	    public void setPossibleDuplicate(Boolean possibleDuplicate) {
193	        this.possibleDuplicate = possibleDuplicate;
194	    }
195	
196	    public Integer getPossibleDuplicateOf() {
197	        return this.possibleDuplicateOf;
198	    }
199	
200	    public void setPossibleDuplicateOf(Integer possibleDuplicateOf) {
201	        this.possibleDuplicateOf = possibleDuplicateOf;
202	    }
