204	    public LocalDate getBirthDate() {
205	        return this.birthDate;
206	    }
207	
208	    public void setBirthDate(LocalDate birthDate) {
209	        this.birthDate = birthDate;
210	    }
211	
212	    /**
213	     * The owner's membership points, derived on read from the fields assigned at create. Points
214	     * start at 0 and accumulate: 2 when an email is present, 1 when {@code namesakeCount} is 0,
215	     * 2 when the household has 3 or more members ({@code householdMemberCount} of 3 or more), and
216	     * 3 when the owner's tenure exceeds 365 days. Tenure is the number of whole days between the
217	     * {@code registrationDate} and the current date. Because a newly created owner has zero tenure,
218	     * the tenure points are only earned once the owner's tenure passes 365 days.
219	     *
220	     * @return the membership points, 0 or more
221	     */
222	    @Transient
223	    public Integer getMembershipPoints() {
224	        int points = 0;
225	        if (this.email != null && !this.email.isBlank()) {
226	            points += 2;
227	        }
228	        if (this.namesakeCount != null && this.namesakeCount == 0) {
229	            points += 1;
230	        }
231	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
232	            points += 2;
233	        }
234	        if (this.registrationDate != null
235	                && ChronoUnit.DAYS.between(this.registrationDate, LocalDate.now()) > 365) {
236	            points += 3;
237	        }
238	        return points;
239	    }
240	
241	    /**
242	     * The owner's numeric membership level, derived on read by mapping {@link #getMembershipPoints}
243	     * to a level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
244	     * Because a newly created owner has zero tenure, level 4 (which requires the tenure points) is
245	     * reached only once the owner's tenure passes 365 days.
246	     *
247	     * @return the membership level, from 1 to 4
248	     */
249	    @Transient
250	    public Integer getMembershipLevel() {
251	        int points = getMembershipPoints();
252	        if (points >= 6) {
253	            return 4;
254	        }
255	        if (points >= 4) {
256	            return 3;
257	        }
258	        if (points >= 2) {
259	            return 2;
260	        }
261	        return 1;
262	    }
263	
264	    /**
265	     * The owner's preferred contact channel, derived on read: {@code 'EMAIL'} when an
266	     * email address is present, otherwise {@code 'PHONE'}.
267	     *
268	     * @return {@code "EMAIL"} when an email is present, otherwise {@code "PHONE"}
269	     */
270	    @Transient
271	    public String getContactPreference() {
272	        return (this.email != null && !this.email.isBlank()) ? "EMAIL" : "PHONE";
273	    }
274	
275	    /**
276	     * The owner's age band, derived on read from {@code birthDate} against the
277	     * {@code registrationDate}: {@code 'MINOR'} when the owner is under 18, {@code 'ADULT'}
278	     * from 18 to 64, and {@code 'SENIOR'} at 65 or older. The age is the number of whole years
279	     * between the birth date and the registration date (falling back to the current date when no
280	     * registration date is set).
281	     *
282	     * @return the age band, or {@code null} when no {@code birthDate} is set
283	     */
284	    @Transient
285	    public String getAgeBand() {
286	        if (this.birthDate == null) {
287	            return null;
288	        }
289	        LocalDate reference = this.registrationDate != null ? this.registrationDate : LocalDate.now();
290	        int age = Period.between(this.birthDate, reference).getYears();
291	        if (age < 18) {
292	            return "MINOR";
293	        }
294	        if (age < 65) {
295	            return "ADULT";
296	        }
297	        return "SENIOR";
298	    }
299	
300	    /**
301	     * The owner's check digit, derived on read: a single Luhn check digit computed over the
302	     * digits contained in the owner's {@code customerCode}.
303	     *
304	     * @return the Luhn check digit (0-9), or {@code null} when no customer code is assigned
305	     */
306	    @Transient
307	    public Integer getCheckDigit() {
308	        if (this.customerCode == null) {
309	            return null;
310	        }
311	        int sum = 0;
312	        boolean dbl = true;
313	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
314	            char c = this.customerCode.charAt(i);
315	            if (c < '0' || c > '9') {
316	                continue;
317	            }
318	            int d = c - '0';
319	            if (dbl) {
320	                d *= 2;
321	                if (d > 9) {
322	                    d -= 9;
323	                }
324	            }
325	            sum += d;
326	            dbl = !dbl;
327	        }
328	        return (10 - (sum % 10)) % 10;
329	    }
330	
331	    /**
332	     * The owner's stored E.164 {@code telephone} formatted for humans, derived on read: the
333	     * leading {@code '+'} and country code, a space, then the national digits grouped in threes
334	     * (e.g. {@code '+61 412 345 678'} for a stored {@code '+61412345678'}). The recognised
335	     * country codes are {@code '+61'} (Australia) and {@code '+1'} (NANP); any other prefix falls
336	     * back to a two-digit country code. The raw {@code telephone} is left in E.164 form.
337	     *
338	     * @return the human-formatted telephone, or the raw value when it is not in E.164 form
339	     */
340	    @Transient
341	    public String getTelephoneDisplay() {
342	        if (this.telephone == null || !this.telephone.startsWith("+")
343	                || !this.telephone.substring(1).matches("[0-9]+")) {
344	            return this.telephone;
345	        }
346	        String digits = this.telephone.substring(1);
347	        String countryCode;
348	        if (digits.startsWith("61")) {
349	            countryCode = "61";
350	        } else if (digits.startsWith("1")) {
351	            countryCode = "1";
352	        } else {
353	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
354	        }
355	        String national = digits.substring(countryCode.length());
356	        StringBuilder display = new StringBuilder("+").append(countryCode);
357	        for (int i = 0; i < national.length(); i += 3) {
358	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
359	        }
360	        return display.toString();
361	    }
362	
363	    /**
364	     * The owner's derived duplicate-detection key: the single consolidated identity used to
365	     * detect duplicate owners on create. It is formed as
366	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} from the
367	     * owner's already-normalized {@code telephone} (E.164 form), its lower-cased {@code email}
368	     * (empty when absent) and its assigned {@code householdId}. Two owners are duplicates only
369	     * when their whole {@code identityKey} values are equal.
370	     *
371	     * @return the consolidated identity key
372	     */
373	    @Transient
374	    public String getIdentityKey() {
375	        String telephonePart = this.telephone == null ? "" : this.telephone;
376	        String emailPart = this.email == null ? "" : this.email;
377	        String householdPart = this.householdId == null ? "" : this.householdId;
378	        return telephonePart + "|" + emailPart + "|" + householdPart;
379	    }
380	
381	    protected Set<Pet> getPetsInternal() {
382	        if (this.pets == null) {
383	            this.pets = new HashSet<>();
384	        }
385	        return this.pets;
386	    }
387	
388	    protected void setPetsInternal(Set<Pet> pets) {
389	        this.pets = pets;
390	    }
391	
392	    public List<Pet> getPets() {
393	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
394	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
395	        return Collections.unmodifiableList(sortedPets);
396	    }
397	
398	    public void setPets(List<Pet> pets) {
399	        this.pets = new HashSet<>(pets);
400	    }
401	
402	    public void addPet(Pet pet) {
403	        getPetsInternal().add(pet);
404	        pet.setOwner(this);
405	    }
406	
407	    /**
408	     * Return the Pet with the given name, or null if none found for this Owner.
409	     *
410	     * @param name to test
411	     * @return true if pet name is already in use
412	     */
413	    public Pet getPet(String name) {
414	        return getPet(name, false);
415	    }
416	
417	    /**
418	     * Return the Pet with the given name, or null if none found for this Owner.
419	     *
420	     * @param name to test
421	     * @return true if pet name is already in use
422	     */
423	    public Pet getPet(String name, boolean ignoreNew) {
424	        name = name.toLowerCase();
425	        for (Pet pet : getPetsInternal()) {
426	            if (!ignoreNew || !pet.isNew()) {
427	                String compName = pet.getName();
428	                compName = compName.toLowerCase();
429	                if (compName.equals(name)) {
430	                    return pet;
431	                }
432	            }
433	        }
434	        return null;
435	    }
436	
437	    public Pet getPet(Integer petId) {
438	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
439	    }
440	
441	    @Override
442	    public String toString() {
443	        return new ToStringCreator(this)
444	
445	            .append("id", this.getId())
446	            .append("new", this.isNew())
447	            .append("lastName", this.getLastName())
448	            .append("firstName", this.getFirstName())
449	            .append("address", this.address)
450	            .append("city", this.city)
451	            .append("telephone", this.telephone)
452	            .append("email", this.email)
453	            .toString();
454	    }
455	}
