242	    /**
243	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
244	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
245	     * Validation already rejects {@code null} values and the pattern-constrained fields
246	     * when blank, but {@code address} and {@code city} have no pattern, so a
247	     * whitespace-only value would otherwise slip through.
248	     *
249	     * @param ownerFieldsDto the submitted owner fields
250	     * @throws RequiredFieldsMissingException if any required field is missing or blank
251	     */
252	    /**
253	     * Common street-type abbreviations expanded during address normalization. Keys are the
254	     * upper-cased abbreviation tokens; values are their canonical expansions.
255	     */
256	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
257	        "ST", "STREET",
258	        "RD", "ROAD",
259	        "AVE", "AVENUE");
260	
261	    /**
262	     * Normalizes the submitted address on create and writes the canonical value back onto the
263	     * request so it is persisted, echoed back, and used for every downstream address comparison
264	     * (household duplicate detection and the household id). The value is trimmed, internal
265	     * whitespace runs are collapsed to a single space, it is upper-cased, and common street-type
266	     * abbreviations are expanded token-by-token (see {@link #ADDRESS_ABBREVIATIONS}). A
267	     * {@code null} address is left untouched so the required-field check can report it as missing.
268	     *
269	     * @param ownerFieldsDto the submitted owner fields
270	     */
271	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
272	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
273	    }
274	
275	    /**
276	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
277	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
278	     * expanded to its full form. A {@code null} value is returned unchanged.
279	     *
280	     * @param raw the address to canonicalize, possibly {@code null}
281	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
282	     */
283	    private static String normalizeAddress(String raw) {
284	        if (raw == null) {
285	            return null;
286	        }
287	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
288	        if (collapsed.isEmpty()) {
289	            return collapsed;
290	        }
291	        String[] tokens = collapsed.split(" ");
292	        StringBuilder sb = new StringBuilder(collapsed.length());
293	        for (int i = 0; i < tokens.length; i++) {
294	            if (i > 0) {
295	                sb.append(' ');
296	            }
297	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
298	        }
299	        return sb.toString();
300	    }
