302	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
303	        List<String> errors = new ArrayList<>();
304	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
305	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
306	        requireText("address", ownerFieldsDto.getAddress(), errors);
307	        requireText("city", ownerFieldsDto.getCity(), errors);
308	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
309	        if (!errors.isEmpty()) {
310	            throw new RequiredFieldsMissingException(errors);
311	        }
312	    }
