320	    /**
321	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
322	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
323	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
324	     */
325	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
326	        "NSW", new int[] {2000, 2099},
327	        "VIC", new int[] {3000, 3099},
328	        "QLD", new int[] {4000, 4099});
329	
330	    /**
331	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
332	     * {@code null} value is accepted. When present it has already been constrained to four digits
333	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
334	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
335	     * the postcode must fall within that region's inclusive range
336	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
337	     *
338	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
339	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
340	     *                                  city's region
341	     */
342	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
343	        String postcode = ownerFieldsDto.getPostcode();
344	        if (postcode == null) {
345	            return;
346	        }
347	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
348	            .regionFor(ownerFieldsDto.getCity());
349	        int[] range = REGION_POSTCODE_RANGE.get(region);
350	        if (range == null) {
351	            return;
352	        }
353	        int value = Integer.parseInt(postcode);
354	        if (value < range[0] || value > range[1]) {
355	            throw new InvalidPostcodeException(postcode);
356	        }
357	    }
