360	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
361	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
362	     * and echoed back in that form.
363	     *
364	     * @param ownerFieldsDto the submitted owner fields
365	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
366	     *                                        valid E.164 number
367	     */
368	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
369	        String e164 = toE164(ownerFieldsDto.getTelephone());
370	        if (e164 == null) {
371	            throw new RequiredFieldsMissingException(List.of("telephone"));
372	        }
373	        ownerFieldsDto.setTelephone(e164);
