376	    /**
377	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
378	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
379	     * and country code are present they are kept; otherwise country code {@code '+61'} is
380	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
381	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
382	     * the national-number length must match the country: {@code '+61'} (Australia) requires
383	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
384	     *
385	     * @param raw the submitted telephone, possibly {@code null}
386	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
387	     */
388	    private static String toE164(String raw) {
389	        if (raw == null) {
390	            return null;
391	        }
392	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
393	        String digits;
394	        if (cleaned.startsWith("+")) {
395	            digits = cleaned.substring(1);
396	        } else {
397	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
398	            digits = "61" + national;
399	        }
400	        if (!digits.matches("[0-9]{8,15}")) {
401	            return null;
402	        }
403	        if (digits.startsWith("61")) {
404	            // Australia: exactly 9 national digits after the '+61' country code.
405	            if (digits.length() - 2 != 9) {
406	                return null;
407	            }
408	        } else if (digits.startsWith("1")) {
409	            // NANP: exactly 10 national digits after the '+1' country code.
410	            if (digits.length() - 1 != 10) {
411	                return null;
412	            }
413	        }
414	        return "+" + digits;
415	    }
