417	    /**
418	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
419	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
420	     * each stored owner's telephone is normalized the same way before comparison so differing
421	     * input formats collapse to the same value.
422	     *
423	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
424	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
425	     *                                     same E.164 telephone
426	     */
427	    /**
428	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
429	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
430	     * the parts may contain whitespace or a second {@code @}.
431	     */
432	    private static final Pattern EMAIL_PATTERN =
433	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
434	
435	    /**
436	     * Disposable email domains that are not accepted for an owner's email. A create whose email
437	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
438	     * rejected. Kept lower-cased to match the normalized email.
439	     */
440	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
441	        "mailinator.com",
442	        "tempmail.com",
443	        "guerrillamail.com");
444	
445	    /**
446	     * Normalizes the submitted email when present: the value is trimmed, required to be a
447	     * syntactically valid address, required not to use a disposable-email domain, and written back
448	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
449	     * left untouched — the field is optional.
450	     *
451	     * @param ownerFieldsDto the submitted owner fields
452	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
453	     *                               valid, or its domain is on the disposable-domain blocklist
454	     */
455	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
456	        String email = ownerFieldsDto.getEmail();
457	        if (email == null) {
458	            return;
459	        }
460	        String trimmed = email.strip();
461	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
462	            throw new InvalidEmailException(email);
463	        }
464	        String normalized = trimmed.toLowerCase(Locale.ROOT);
465	        String domain = normalized.substring(normalized.indexOf('@') + 1);
466	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
467	            throw new InvalidEmailException(email);
468	        }
469	        ownerFieldsDto.setEmail(normalized);
470	    }
