472	    /**
473	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
474	     * date. A registration may be back-dated but never post-dated. The check is made against the
475	     * value as supplied, before any defaulting or business-day roll (see
476	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
477	     * to the server date).
478	     *
479	     * @param ownerFieldsDto the submitted owner fields
480	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
481	     *                                         after the server's current date
482	     */
483	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
484	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
485	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
486	            throw new FutureRegistrationDateException(supplied);
487	        }
488	    }
