490	    /**
491	     * Establishes the effective registration date on create and rolls it onto a business day.
492	     * When the client does not supply a {@code registrationDate} it defaults to the server's
493	     * current date; the resulting date (supplied or defaulted) is then rolled forward to the
494	     * next Monday when it falls on a Saturday or Sunday (see {@link #toBusinessDay}). The
495	     * adjusted value is written back onto the request so it is persisted, echoed back in ISO
496	     * 'YYYY-MM-DD' format, and used by every value derived from the registration date (such as
497	     * the membership number's year segment and the daily create-limit).
498	     *
499	     * @param ownerFieldsDto the submitted owner fields
500	     */
501	    private static void defaultRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
502	        LocalDate effective = ownerFieldsDto.getRegistrationDate();
503	        if (effective == null) {
504	            effective = LocalDate.now();
505	        }
506	        ownerFieldsDto.setRegistrationDate(toBusinessDay(effective));
507	    }
