509	    /**
510	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
511	     * following Monday; any weekday is returned unchanged.
512	     *
513	     * @param date the date to adjust
514	     * @return the same date when it is a weekday, otherwise the next Monday
515	     */
516	    private static LocalDate toBusinessDay(LocalDate date) {
517	        return switch (date.getDayOfWeek()) {
518	            case SATURDAY -> date.plusDays(2);
519	            case SUNDAY -> date.plusDays(1);
520	            default -> date;
521	        };
522	    }
