524	    /**
525	     * Assigns the owner's {@code customerCode} on create, formatted
526	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
527	     * (preferring the postcode range, falling back to the city — the same derivation that yields
528	     * the owner's {@code locality}, see
529	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
530	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
531	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
532	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
533	     * customer code only when their normalized telephone and last name both match.
534	     *
535	     * <p>When the computed customer code collides with an existing owner's {@code customerCode},
536	     * it is de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
537	     * makes it unique among the existing owners, so distinct owners always receive distinct codes.
538	     *
539	     * @param owner the owner being created (with its {@code postcode}, {@code city},
540	     *              {@code telephone} and {@code lastName} already set)
541	     */
542	    private void assignCustomerCode(Owner owner) {
543	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
544	            .regionFor(owner.getPostcode(), owner.getCity());
545	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
546	            .substring(0, 8).toUpperCase(Locale.ROOT);
547	        String base = region + "-" + hash8;
548	        Set<String> existing = this.clinicService.findAllOwners().stream()
549	            .map(Owner::getCustomerCode)
550	            .filter(Objects::nonNull)
551	            .collect(Collectors.toSet());
552	        String customerCode = base;
553	        for (int n = 2; existing.contains(customerCode); n++) {
554	            customerCode = base + "-" + n;
555	        }
556	        owner.setCustomerCode(customerCode);
557	    }
