559	    /**
560	     * Assigns the owner's {@code householdId} on create: a stable, deterministic identifier for
561	     * the household, the first 12 hex characters of the SHA-256 digest of the owner's normalized
562	     * {@code lastName} and {@code postcode} (see {@link #householdIdFor}). Because it is derived
563	     * purely from those two fields, every owner sharing a last name and postcode is assigned the
564	     * same value automatically — including one joining an existing household via
565	     * {@code sharesHousehold} — independent of create order.
566	     *
567	     * @param owner the owner being created (with its {@code lastName} and {@code postcode} already set)
568	     */
569	    private void assignHouseholdId(Owner owner) {
570	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
571	    }
572	
573	    /**
574	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
575	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
576	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
577	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
578	     * every owner sharing a last name and postcode receives the same value, independent of create
579	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #identityKeyFor}
580	     * (which folds it into the identity key for duplicate detection) and
581	     * {@link #rejectDuplicateHousehold} (which blocks a second owner in the same household).
582	     *
583	     * @param lastName the owner's last name
584	     * @param postcode the owner's postcode, possibly {@code null}
585	     * @return the derived household id
586	     */
587	    private static String householdIdFor(String lastName, String postcode) {
588	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
589	        return sha256Hex(key).substring(0, 12);
590	    }
