592	    /**
593	     * Rejects a create whose computed {@code householdId} (derived from {@code lastName} and
594	     * {@code postcode}, see {@link #householdIdFor}) already belongs to an existing owner, unless
595	     * the request opts in via {@code sharesHousehold}. Because the household is keyed on
596	     * {@code (lastName, postcode)}, a second owner sharing both is the same household: it is
597	     * rejected with a 409 as a household duplicate unless it declares {@code sharesHousehold}, in
598	     * which case it is created as a declared household member. The scan is taken over the existing
599	     * owners before this one is persisted.
600	     *
601	     * @param ownerFieldsDto the submitted owner fields ({@code lastName} and {@code postcode} set)
602	     * @throws DuplicateHouseholdException with a 409 status if the household already exists and the
603	     *                                     request did not opt in via {@code sharesHousehold}
604	     */
605	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
606	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
607	            return;
608	        }
609	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
610	        boolean duplicate = this.clinicService.findAllOwners().stream()
611	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
612	        if (duplicate) {
613	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
614	        }
615	    }
