617	    /**
618	     * Assigns the owner's {@code householdMemberCount} on create: the number of owners in this
619	     * owner's household — those already sharing its {@code householdId} plus this owner itself —
620	     * after this create. Because {@code householdId} is derived from the owner's {@code lastName}
621	     * and {@code postcode} (see {@link #assignHouseholdId}), the count reflects every
622	     * owner registered to the same household, including those who joined via {@code sharesHousehold}.
623	     * The count is taken before this owner is persisted, so it is one more than the number of
624	     * existing household members.
625	     *
626	     * @param owner the owner being created (with its {@code householdId} already assigned)
627	     */
628	    private void assignHouseholdMemberCount(Owner owner) {
629	        String householdId = owner.getHouseholdId();
630	        long existing = this.clinicService.findAllOwners().stream()
631	            .filter(other -> householdId != null && householdId.equals(other.getHouseholdId()))
632	            .count();
633	        owner.setHouseholdMemberCount((int) (existing + 1));
634	    }
