636	    /**
637	     * Assigns the owner's {@code namesakeCount} on create: the number of existing owners that
638	     * already share this owner's {@code firstName} and {@code lastName}, compared
639	     * case-insensitively. The count is taken before this owner is persisted, so it reflects only
640	     * pre-existing namesakes.
641	     *
642	     * @param owner the owner being created (with its {@code firstName} and {@code lastName} already set)
643	     */
644	    private void assignNamesakeCount(Owner owner) {
645	        String firstName = owner.getFirstName();
646	        String lastName = owner.getLastName();
647	        long count = this.clinicService.findAllOwners().stream()
648	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
649	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
650	            .count();
651	        owner.setNamesakeCount((int) count);
652	    }
653	
654	    /**
655	     * Assigns the owner's {@code membershipNumber} on create, formatted
656	     * {@code '<customerCode>-M<YY>'} where customerCode is the owner's already-assigned customer
657	     * code and YY is the last two digits of the {@code registrationDate} year, zero-padded
658	     * (e.g. {@code 'NSW-A1B2C3D4-M26'}). Derived purely from the owner's own fields, so both
659	     * {@link #assignCustomerCode} and {@link #defaultRegistrationDate} must run first.
660	     *
661	     * @param owner the owner being created (with its {@code customerCode} and
662	     *              {@code registrationDate} already set)
663	     */
664	    private void assignMembershipNumber(Owner owner) {
665	        String yy = String.format("%02d", owner.getRegistrationDate().getYear() % 100);
666	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
667	    }
668	
669	    /**
670	     * The number of owners that must already carry a registration date before a subsequent
671	     * create for that same day is flagged with a bulk-signup warning. The warning is raised
672	     * once the count of owners already registered on that day <em>exceeds</em> this value.
673	     */
674	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80;
675	
676	    /**
677	     * Assigns the owner's {@code bulkSignupWarning} on create: {@code true} when more than
678	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry this owner's (business-day
679	     * adjusted) {@code registrationDate}, otherwise {@code false}. The count is taken over the
680	     * existing owners before this one is persisted, so it reflects only the owners already
681	     * created for that day (matching the accumulation used by {@link #rejectDailyLimit}).
682	     *
683	     * @param owner the owner being created (with its {@code registrationDate} already set)
684	     */
685	    private void assignBulkSignupWarning(Owner owner) {
686	        LocalDate registrationDate = owner.getRegistrationDate();
687	        long count = this.clinicService.findAllOwners().stream()
688	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
689	            .count();
690	        owner.setBulkSignupWarning(count > BULK_SIGNUP_WARNING_THRESHOLD);
691	    }
692	
693	    /**
694	     * Assigns the owner's soft-match duplicate flags on create. The create has already passed
695	     * {@link #rejectDuplicateIdentity} and {@link #rejectDuplicateHousehold}, so this owner is not
696	     * a hard duplicate. A declared household member (one that opted in via {@code sharesHousehold})
697	     * is never flagged: it is an acknowledged member of the household, not a suspected duplicate,
698	     * so {@code possibleDuplicate} is {@code false}. Otherwise it is a <em>possible</em> duplicate
699	     * when an existing owner shares its {@code lastName} (compared case-insensitively) and its
700	     * {@code postcode} but has a <em>different</em> normalized {@code telephone}:
701	     * {@code possibleDuplicate} is set {@code true} and {@code possibleDuplicateOf} to that owner's
702	     * id (the earliest such owner by id when several match). Otherwise {@code possibleDuplicate} is
703	     * {@code false} and {@code possibleDuplicateOf} is left unset. The scan is taken over the
704	     * existing owners before this one is persisted.
705	     *
706	     * @param owner the owner being created (with its {@code lastName}, {@code postcode} and
707	     *              already-normalized {@code telephone} set)
708	     * @param declaredHouseholdMember whether the request opted in via {@code sharesHousehold}
709	     */
710	    private void assignPossibleDuplicate(Owner owner, boolean declaredHouseholdMember) {
711	        if (declaredHouseholdMember) {
712	            owner.setPossibleDuplicate(false);
713	            owner.setPossibleDuplicateOf(null);
714	            return;
715	        }
716	        String lastName = owner.getLastName();
717	        String postcode = owner.getPostcode();
718	        String telephone = owner.getTelephone();
719	        Integer matchId = null;
720	        if (lastName != null && postcode != null && telephone != null) {
721	            matchId = this.clinicService.findAllOwners().stream()
722	                .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
723	                .filter(existing -> postcode.equals(existing.getPostcode()))
724	                .filter(existing -> !telephone.equals(existing.getTelephone()))
725	                .map(Owner::getId)
726	                .filter(id -> id != null)
727	                .min(Integer::compareTo)
728	                .orElse(null);
729	        }
730	        owner.setPossibleDuplicate(matchId != null);
731	        owner.setPossibleDuplicateOf(matchId);
732	    }
733	
734	    /**
735	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
736	     *
737	     * @param value the string to hash
738	     * @return the 64-character lower-case hex digest
739	     */
740	    private static String sha256Hex(String value) {
741	        try {
742	            byte[] digest = MessageDigest.getInstance("SHA-256")
743	                .digest(value.getBytes(StandardCharsets.UTF_8));
744	            StringBuilder sb = new StringBuilder(digest.length * 2);
745	            for (byte b : digest) {
746	                sb.append(String.format("%02x", b));
747	            }
748	            return sb.toString();
749	        }
750	        catch (NoSuchAlgorithmException e) {
751	            throw new IllegalStateException("SHA-256 not available", e);
752	        }
753	    }
754	
755	    /**
756	     * Rejects a create whose whole derived {@code identityKey} already equals that of an existing
757	     * owner. This single key consolidates what used to be three separate duplicate checks
758	     * (telephone, email and household): the key is
759	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId} (see
760	     * {@link #identityKeyFor}), and a create is a duplicate only when its <em>whole</em> key
761	     * matches an existing owner's. Because the telephone is part of the key, two members of the
762	     * same household (same {@code householdId}) with different telephones have different identity
763	     * keys and are both allowed; only an exact full-key match is rejected. The submitted telephone
764	     * and email have already been normalized by {@link #normalizeTelephone} and
765	     * {@link #normalizeEmail}, and each existing owner's key is computed the same way so differing
766	     * input formats collapse to the same value.
767	     *
768	     * @param ownerFieldsDto the submitted owner fields (telephone and email already normalized)
769	     * @throws DuplicateIdentityException with a 409 status if another owner already has the same
770	     *                                    whole identity key
771	     */
772	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
773	        String identityKey = identityKeyFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode(),
774	            ownerFieldsDto.getTelephone(), ownerFieldsDto.getEmail());
775	        boolean duplicate = this.clinicService.findAllOwners().stream()
776	            .map(owner -> identityKeyFor(owner.getLastName(), owner.getPostcode(),
777	                owner.getTelephone(), owner.getEmail()))
778	            .anyMatch(identityKey::equals);
779	        if (duplicate) {
780	            throw new DuplicateIdentityException(identityKey);
781	        }
782	    }
783	
784	    /**
785	     * Computes an owner's derived {@code identityKey} from its identity-bearing fields:
786	     * {@code normalizedTelephone + '|' + (email or empty) + '|' + householdId}. The telephone is
787	     * normalized to E.164 form (see {@link #toE164}), the email is lower-cased (empty when
788	     * absent), and the {@code householdId} is derived from the {@code lastName} and
789	     * {@code postcode} the same way {@link #assignHouseholdId} assigns it (see
790	     * {@link #householdIdFor}). Deriving every part canonically means two owners collide only when
791	     * their whole identities match, regardless of the exact input formats.
792	     *
793	     * @param lastName  the owner's last name
794	     * @param postcode  the owner's postcode
795	     * @param telephone the owner's telephone, in any format {@link #toE164} accepts
796	     * @param email     the owner's email, possibly {@code null}
797	     * @return the canonical identity key
798	     */
799	    private static String identityKeyFor(String lastName, String postcode, String telephone, String email) {
800	        String normalizedTelephone = toE164(telephone);
801	        String telephonePart = normalizedTelephone == null ? "" : normalizedTelephone;
802	        String emailPart = email == null ? "" : email.strip().toLowerCase(Locale.ROOT);
803	        return telephonePart + "|" + emailPart + "|" + householdIdFor(lastName, postcode);
804	    }
805	
806	    /**
807	     * The maximum number of owners permitted in a single city. A create is rejected once the
808	     * owner's city already contains this many owners.
809	     */
810	    private static final long CITY_CAPACITY = 50;
811	
812	    /**
813	     * Rejects a create whose {@code city} already contains {@link #CITY_CAPACITY} or more owners,
814	     * compared case-insensitively (matching {@link #assignCustomerCode}). The count is taken
815	     * before this owner is persisted.
816	     *
817	     * @param city the submitted city
818	     * @throws CityAtCapacityException with a 409 status if the city is already at capacity
819	     */
820	    private void rejectCityAtCapacity(String city) {
821	        long count = this.clinicService.findAllOwners().stream()
822	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
823	            .count();
824	        if (count >= CITY_CAPACITY) {
825	            throw new CityAtCapacityException(city);
826	        }
827	    }
828	
829	    /**
830	     * The maximum number of owners permitted to be created in a single day. A create is
831	     * rejected once this many owners already carry today's {@code registrationDate}.
832	     */
833	    private static final long DAILY_LIMIT = 100;
834	
835	    /**
836	     * Rejects a create once {@link #DAILY_LIMIT} or more owners already carry the given adjusted
837	     * business day as their {@code registrationDate}. The day counted against is this create's
838	     * effective registration date after the business-day roll (see {@link #defaultRegistrationDate}),
839	     * so owners are counted per adjusted business day. The count is taken before this owner is
840	     * persisted.
841	     *
842	     * @param businessDay the effective, business-day-adjusted registration date of this create
843	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
844	     */
845	    private void rejectDailyLimit(LocalDate businessDay) {
846	        long count = this.clinicService.findAllOwners().stream()
847	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
848	            .count();
849	        if (count >= DAILY_LIMIT) {
850	            throw new DailyOwnerLimitExceededException(businessDay);
851	        }
852	    }
853	
854	    /**
855	     * Canonicalizes a value for household comparison: leading/trailing whitespace is trimmed,
856	     * every internal run of whitespace is collapsed to a single space, and the result is
857	     * lower-cased. A {@code null} value collapses to the empty string.
858	     *
859	     * @param value the value to canonicalize, possibly {@code null}
860	     * @return the collapsed, lower-cased value
861	     */
862	    private static String collapse(String value) {
863	        if (value == null) {
864	            return "";
865	        }
866	        return value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
867	    }
868	
869	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
870	    @Override
871	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
872	        Owner owner = this.clinicService.findOwnerById(ownerId);
873	        if (owner != null) {
874	            Pet pet = owner.getPet(petId);
875	            if (pet != null) {
876	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
877	            }
878	        }
879	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
880	    }
881	}
