9	/** address-structured: structured addressLine1/city/postcode is accepted and normalized (
10	 * rules: upper-case, collapse whitespace, expand ST->STREET), and 'address' is the composed
11	 * normalized string. The flat 'address' form stays accepted (backward-compatible). */
12	@Tag("cp44")
13	class Cp44Tests extends AcceptanceBase {
14	
15		@Test
16		void coreNormalizesAndComposesStructuredAddress() throws Exception {
17			ObjectNode o = structuredOwner();
18			o.put("addressLine1", "10 king st");
19			o.remove("addressLine2");
20			int id = createOwnerOk(o);
21			getOwner(id).andExpect(jsonPath("$.addressLine1").value("10 KING STREET"))
22					.andExpect(jsonPath("$.address").value("10 KING STREET"));
23		}
24	
25		@Test
